using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using NexusOps.Web.Models;using NexusOps.Web.Services;
namespace NexusOps.Web.Pages.Notifications;public sealed class IndexModel(IDemoNotificationStore store):PageModel{[BindProperty]public CreateDemoNotificationInput Input{get;set;}=new(){Channel=DemoChannel.Sms,Message="NexusOps demo: radni nalog je dodijeljen i spreman za obradu."};public IReadOnlyList<DemoNotification> Items{get;private set;}=[];public void OnGet()=>Items=store.List();public IActionResult OnPost(){Items=store.List();if(!User.IsInRole("Administrator")&&!User.IsInRole("Manager"))return Forbid();if(!ModelState.IsValid)return Page();try{store.Send(Input);TempData["Success"]="Demo obavijest je simulirana — ništa nije stvarno poslano.";return RedirectToPage();}catch(ArgumentException e){ModelState.AddModelError(string.Empty,e.Message);return Page();}}}
